const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function download(url){const target=path.join(cache,sha256(url));if(fs.existsSync(target)&&fs.statSync(target).size>1000)return fs.readFileSync(target);let last;for(let n=1;n<=6;n++){const res=await fetch(url,{redirect:"follow",headers:{"user-agent":"History-Go-place-production/1.0 (Paradispartiet/History-Go)"}});if(res.ok){const buffer=Buffer.from(await res.arrayBuffer());fs.writeFileSync(target,buffer);await sleep(2500);return buffer;}last=new Error(`${res.status} ${url}`);if(res.status!==429&&res.status<500)throw last;await sleep(Math.min(30000,3000*n));}throw last;}
