const storyFile="data/stories/stories_akershus_slottskirke.json";write(storyFile,[{id:"st_akershus_slottskirke_olav_v_1991",quality_profile:"episode_v1",type:"ritual_transition",title:"Fra domkirken til slottskirken",year:1991,place_id:placeId,summary:"Etter Olav Vs gravferd i Oslo domkirke fortsatte det kongelige gravritualet i Akershus slottskirke før kisten ble ført til mausoleet.",story:"30. januar 1991 ble kong Olav V gravlagt fra Oslo domkirke. Da seremonien i domkirken var over, ble båren ført videre til Akershus. Slottskirken var ikke sluttpunktet, men et eget ledd i ritualet.\n\nI kirkerommet fant jordpåkastelsen sted. Handlingen bandt den offentlige gravferden til den kongelige gravkirken og markerte overgangen før kisten skulle inn i gravrommet. Kildene skiller dermed mellom tre steder med ulike funksjoner: domkirken, slottskirken og mausoleet.\n\nEtter ritualet i slottskirken ble kisten ført videre til Det kongelige mausoleum. For Akershus slottskirke viser hendelsen hvorfor kirken ikke bare er et historisk interiør. Rommet har vært brukt i konkrete kongelige gravritualer også i nyere tid.",episode:{actors:["Olav V","Den kongelige familie","kirkelige medvirkende"],date:"1991-01-30",action:"Båren ble ført fra Oslo domkirke til Akershus slottskirke, der jordpåkastelsen fant sted.",consequence:"Kisten ble deretter ført videre til Det kongelige mausoleum."},sources:[{title:"Kongehuset – tronskiftet 1991",url:urls.tronskifte},{title:"Kongehuset – Det kongelige mausoleum",url:urls.kongehuset}],tags:["gravferd","ritual","kongehus","1991"],related_people:["olav_v"],related_places:["akershus_slott"],next_scenes:[{place_id:"akershus_slott",reason:"Fortsett fra kirkerommet til slottets øvrige seremonielle rom."}],score:{narrative:4,historical:4,source:4,play_value:3,originality:3,total:18},arc:{start:"Olav Vs gravferd avsluttes i Oslo domkirke.",middle:"Båren føres til slottskirken for jordpåkastelse.",end:"Kisten føres videre til mausoleet."}}]);const sm=read("data/stories/stories_manifest.json");sm.files=sm.files.filter(x=>x.entity_id!==placeId);sm.files.push({category:"religion",entity_id:placeId,path:storyFile});write("data/stories/stories_manifest.json",sm);const em=read("data/stories/stories_episode_v1_manifest.json");addOnce(em.files,storyFile);write("data/stories/stories_episode_v1_manifest.json",em);

